            int src_index = (j + 2) % PRESENT_80_KEY_SIZE_BYTES;
            unsigned char left_bits = key[src_index] << 3;
            unsigned char right_bits = key[(j + 3) % PRESENT_80_KEY_SIZE_BYTES] >> 5;
            temp[j] = left_bits | right_bits;
