        (*block)[i] = (high_nibble << 4) | low_nibble;
    }
}

void pLayer(block_t *block) {
    block_t temp_block = {0};

    for (int i = 0; i < 64; i++) {
        int bit_pos = (i * 16 + i / 4) % 63;
        if (i * 16 + i / 4 >= 63) {
